//! Checkpoint 2, behaviour tests: does the library do what SPEC.md says?
//!
//! Run: cargo test --test behaviour
//!
//! All of these must pass, in debug and with `--release`, for the "pass"
//! level in RUBRIC.md. Do not edit this file.

mod common;

use std::collections::HashSet;
use std::error::Error;

use postage::carrier::{Carrier, Dash, Discounted, Region, Snail, Zone};
use postage::parcel::{Contents, Dimensions, Grams, Parcel, ParcelError, SizeClass};
use postage::quote::{cheapest, total};

const GOODS: Contents = Contents::Goods { fragile: false };
const FRAGILE: Contents = Contents::Goods { fragile: true };
const NEAR: Zone = Zone::International(Region::Near);
const FAR: Zone = Zone::International(Region::Far);
const ZONES: [Zone; 4] = [Zone::Local, Zone::National, NEAR, FAR];

fn parcel(grams: u32, sides: (u32, u32, u32), contents: Contents) -> Parcel {
    let dimensions = Dimensions::new(sides.0, sides.1, sides.2).expect("valid sides");
    Parcel::new(Grams::new(grams), dimensions, contents).expect("valid parcel")
}

fn letter() -> Parcel {
    parcel(50, (220, 110, 3), Contents::Documents)
}

/// Small. 1500 g; by volume it would count as 1200 g.
fn small() -> Parcel {
    parcel(1500, (300, 200, 100), GOODS)
}

/// Medium. 8000 g; by volume it counts as 14 400 g.
fn medium() -> Parcel {
    parcel(8000, (600, 400, 300), GOODS)
}

/// Large. 20 000 g; by volume it counts as 72 000 g.
fn large() -> Parcel {
    parcel(20_000, (1200, 600, 500), GOODS)
}

/// Small. 750 ml in a box of 2 litres.
fn bottle() -> Parcel {
    parcel(1000, (200, 100, 100), Contents::Liquid { millilitres: 750 })
}

/// A carrier written outside the library: one price for everything.
struct Fixed(&'static str, u32);

impl Carrier for Fixed {
    fn name(&self) -> &str {
        self.0
    }
    fn price(&self, _parcel: &Parcel, _zone: Zone) -> Option<u32> {
        Some(self.1)
    }
}

/// A carrier written outside the library: takes nothing.
struct Closed;

impl Carrier for Closed {
    fn name(&self) -> &str {
        "Closed"
    }
    fn price(&self, _parcel: &Parcel, _zone: Zone) -> Option<u32> {
        None
    }
}

// ------------------------------------------------------------------ grams

#[test]
fn grams_wrap_a_number() {
    assert_eq!(Grams::new(250).get(), 250);
    assert_eq!(Grams::new(u32::MAX).get(), u32::MAX);
    assert_eq!(Grams::default(), Grams::new(0));
    assert_eq!(Grams::new(250).to_string(), "250 g");
}

#[test]
fn grams_compare_like_numbers() {
    assert!(Grams::new(999) < Grams::new(1000));
    assert!(
        Grams::new(1000) > Grams::new(2),
        "1000 g is more than 2 g; do not compare as text"
    );
    assert_eq!(Grams::new(7).max(Grams::new(9)), Grams::new(9));
    let set: HashSet<Grams> = [5, 7, 5].into_iter().map(Grams::new).collect();
    assert_eq!(set.len(), 2);
}

// ------------------------------------------------------------- dimensions

#[test]
fn dimensions_are_sorted_whatever_the_argument_order() {
    for (a, b, c) in [(30, 20, 10), (10, 20, 30), (20, 30, 10), (10, 30, 20)] {
        let d = Dimensions::new(a, b, c).unwrap();
        assert_eq!(
            (d.longest(), d.middle(), d.shortest()),
            (30, 20, 10),
            "new({a}, {b}, {c})"
        );
    }
    let cube = Dimensions::new(7, 7, 7).unwrap();
    assert_eq!((cube.longest(), cube.middle(), cube.shortest()), (7, 7, 7));
}

#[test]
fn a_box_turned_on_its_side_is_the_same_box() {
    assert_eq!(Dimensions::new(30, 20, 10), Dimensions::new(10, 30, 20));
    assert_ne!(Dimensions::new(30, 20, 10), Dimensions::new(30, 20, 11));
    assert_eq!(
        parcel(500, (30, 20, 10), GOODS),
        parcel(500, (20, 10, 30), GOODS),
        "two parcels with the same weight, contents and box are equal"
    );
    assert_ne!(
        parcel(500, (30, 20, 10), GOODS),
        parcel(500, (30, 20, 10), FRAGILE)
    );
}

#[test]
fn dimensions_reject_sides_outside_the_range() {
    assert_eq!(Dimensions::MAX_SIDE_MM, 2000);
    assert!(Dimensions::new(1, 1, 1).is_ok());
    assert!(Dimensions::new(2000, 2000, 2000).is_ok());
    assert_eq!(Dimensions::new(0, 5, 5), Err(ParcelError::Side(0)));
    assert_eq!(Dimensions::new(5, 5, 2001), Err(ParcelError::Side(2001)));
    assert_eq!(
        Dimensions::new(5, 3000, 0),
        Err(ParcelError::Side(3000)),
        "the error names the first bad argument, in the order of the call"
    );
    assert_eq!(Dimensions::new(0, 9999, 5), Err(ParcelError::Side(0)));
}

#[test]
fn volume_is_the_product_of_the_sides() {
    assert_eq!(
        Dimensions::new(300, 200, 100).unwrap().volume_mm3(),
        6_000_000
    );
    assert_eq!(Dimensions::new(1, 1, 1).unwrap().volume_mm3(), 1);
}

// ---------------------------------------------------------------- parcels

#[test]
fn parcel_keeps_what_it_was_given() {
    let dimensions = Dimensions::new(100, 300, 200).unwrap();
    let p = Parcel::new(Grams::new(1500), dimensions, FRAGILE).unwrap();
    assert_eq!(p.weight(), Grams::new(1500));
    assert_eq!(p.dimensions(), dimensions);
    assert_eq!(p.contents(), FRAGILE);
}

#[test]
fn parcel_weight_must_be_in_range() {
    assert_eq!(Parcel::MAX_WEIGHT_G, 30_000);
    let d = Dimensions::new(100, 100, 100).unwrap();
    assert!(Parcel::new(Grams::new(1), d, GOODS).is_ok());
    assert!(Parcel::new(Grams::new(30_000), d, GOODS).is_ok());
    assert_eq!(
        Parcel::new(Grams::new(0), d, GOODS),
        Err(ParcelError::Weight(Grams::new(0)))
    );
    assert_eq!(
        Parcel::new(Grams::new(30_001), d, GOODS),
        Err(ParcelError::Weight(Grams::new(30_001)))
    );
}

#[test]
fn parcel_liquid_must_fit_in_the_box() {
    // 100 mm cubed is exactly one litre.
    let litre = Dimensions::new(100, 100, 100).unwrap();
    let weight = Grams::new(1200);
    assert!(Parcel::new(weight, litre, Contents::Liquid { millilitres: 0 }).is_ok());
    assert!(Parcel::new(weight, litre, Contents::Liquid { millilitres: 1000 }).is_ok());
    assert_eq!(
        Parcel::new(weight, litre, Contents::Liquid { millilitres: 1001 }),
        Err(ParcelError::Liquid(1001))
    );
    assert_eq!(
        Parcel::new(Grams::new(0), litre, Contents::Liquid { millilitres: 1001 }),
        Err(ParcelError::Weight(Grams::new(0))),
        "the weight is checked before the liquid"
    );
}

#[test]
fn parcel_error_messages() {
    assert_eq!(
        ParcelError::Side(0).to_string(),
        "side of 0 mm is outside 1..=2000 mm"
    );
    assert_eq!(
        ParcelError::Weight(Grams::new(30_001)).to_string(),
        "weight of 30001 g is outside 1..=30000 g"
    );
    assert_eq!(
        ParcelError::Liquid(750).to_string(),
        "750 ml of liquid do not fit in the parcel"
    );
    let boxed: Box<dyn Error + Send + Sync> = Box::new(ParcelError::Side(5));
    assert!(boxed.source().is_none());
}

#[test]
fn billable_weight_is_the_greater_of_weight_and_volume() {
    assert_eq!(
        small().billable(),
        Grams::new(1500),
        "6 000 000 mm3 count as 1200 g; 1500 g is more"
    );
    assert_eq!(
        medium().billable(),
        Grams::new(14_400),
        "72 000 000 mm3 count as 14 400 g"
    );
    assert_eq!(letter().billable(), Grams::new(50));
    assert_eq!(
        parcel(1, (1667, 3, 1), GOODS).billable(),
        Grams::new(2),
        "5001 mm3 are one cubic millimetre more than 1 g: the volume is rounded up"
    );
    assert_eq!(
        parcel(1, (2000, 5, 1), GOODS).billable(),
        Grams::new(2),
        "10 000 mm3 are exactly 2 g: nothing to round"
    );
}

// ------------------------------------------------------------ size classes

#[test]
fn size_class_order() {
    assert!(SizeClass::Letter < SizeClass::Small);
    assert!(SizeClass::Small < SizeClass::Medium);
    assert!(SizeClass::Medium < SizeClass::Large);
    let mut classes = [
        SizeClass::Large,
        SizeClass::Letter,
        SizeClass::Medium,
        SizeClass::Small,
    ];
    classes.sort();
    assert_eq!(
        classes,
        [
            SizeClass::Letter,
            SizeClass::Small,
            SizeClass::Medium,
            SizeClass::Large
        ]
    );
    assert_eq!(classes.iter().max(), Some(&SizeClass::Large));
}

#[test]
fn size_class_of_the_sample_parcels() {
    assert_eq!(letter().size_class(), SizeClass::Letter);
    assert_eq!(small().size_class(), SizeClass::Small);
    assert_eq!(medium().size_class(), SizeClass::Medium);
    assert_eq!(large().size_class(), SizeClass::Large);
    assert_eq!(bottle().size_class(), SizeClass::Small);
}

#[test]
fn size_class_letter_limits() {
    let doc = Contents::Documents;
    assert_eq!(
        parcel(100, (240, 165, 5), doc).size_class(),
        SizeClass::Letter
    );
    assert_eq!(
        parcel(100, (5, 240, 165), doc).size_class(),
        SizeClass::Letter
    );
    assert_eq!(
        parcel(101, (240, 165, 5), doc).size_class(),
        SizeClass::Small
    );
    assert_eq!(
        parcel(100, (241, 165, 5), doc).size_class(),
        SizeClass::Small
    );
    assert_eq!(
        parcel(100, (240, 166, 5), doc).size_class(),
        SizeClass::Small
    );
    assert_eq!(
        parcel(100, (240, 165, 6), doc).size_class(),
        SizeClass::Small
    );
    assert_eq!(
        parcel(100, (240, 165, 5), GOODS).size_class(),
        SizeClass::Small,
        "only documents travel as a letter"
    );
}

#[test]
fn size_class_small_and_medium_limits() {
    assert_eq!(
        parcel(2000, (450, 350, 160), GOODS).size_class(),
        SizeClass::Small
    );
    assert_eq!(
        parcel(2001, (450, 350, 160), GOODS).size_class(),
        SizeClass::Medium
    );
    assert_eq!(
        parcel(2000, (451, 350, 160), GOODS).size_class(),
        SizeClass::Medium
    );
    assert_eq!(
        parcel(2000, (450, 351, 160), GOODS).size_class(),
        SizeClass::Medium
    );
    assert_eq!(
        parcel(2000, (450, 350, 161), GOODS).size_class(),
        SizeClass::Medium
    );

    assert_eq!(
        parcel(10_000, (800, 500, 400), GOODS).size_class(),
        SizeClass::Medium
    );
    assert_eq!(
        parcel(10_001, (800, 500, 400), GOODS).size_class(),
        SizeClass::Large
    );
    assert_eq!(
        parcel(10_000, (801, 500, 400), GOODS).size_class(),
        SizeClass::Large
    );
    assert_eq!(
        parcel(10_000, (800, 501, 400), GOODS).size_class(),
        SizeClass::Large
    );
    assert_eq!(
        parcel(10_000, (800, 500, 401), GOODS).size_class(),
        SizeClass::Large
    );
    assert_eq!(
        parcel(50, (700, 20, 20), Contents::Documents).size_class(),
        SizeClass::Medium,
        "a light, thin, long roll is too long for Small"
    );
    assert_eq!(
        parcel(30_000, (1, 1, 1), GOODS).size_class(),
        SizeClass::Large
    );
}

// ------------------------------------------------------------------ snail

#[test]
fn snail_price_table() {
    assert_eq!(Snail.name(), "Snail Mail");
    let table = [
        (letter(), [Some(90), Some(110), Some(250), Some(400)]),
        (small(), [Some(400), Some(550), Some(1400), Some(2600)]),
        (medium(), [Some(700), Some(950), Some(3100), None]),
        (large(), [Some(1500), Some(1900), None, None]),
    ];
    for (p, prices) in table {
        for (zone, expected) in ZONES.into_iter().zip(prices) {
            assert_eq!(
                Snail.price(&p, zone),
                expected,
                "{:?} to {zone:?}",
                p.size_class()
            );
        }
    }
}

#[test]
fn snail_adds_a_surcharge_for_fragile_goods() {
    let vase = parcel(1500, (300, 200, 100), FRAGILE);
    assert_eq!(Snail.price(&vase, Zone::Local), Some(600));
    assert_eq!(Snail.price(&vase, FAR), Some(2800));
    let big_vase = parcel(8000, (600, 400, 300), FRAGILE);
    assert_eq!(
        Snail.price(&big_vase, FAR),
        None,
        "a surcharge does not make a declined parcel acceptable"
    );
}

#[test]
fn snail_takes_liquid_only_inside_the_country() {
    assert_eq!(Snail.price(&bottle(), Zone::Local), Some(400));
    assert_eq!(Snail.price(&bottle(), Zone::National), Some(550));
    assert_eq!(Snail.price(&bottle(), NEAR), None);
    assert_eq!(Snail.price(&bottle(), FAR), None);
}

#[test]
fn accepts_follows_the_price_by_default() {
    for zone in ZONES {
        for p in [letter(), small(), medium(), large(), bottle()] {
            assert_eq!(Snail.accepts(&p, zone), Snail.price(&p, zone).is_some());
        }
    }
    assert!(
        Fixed("F", 1).accepts(&small(), FAR),
        "a carrier from another crate gets `accepts` for free"
    );
    assert!(!Closed.accepts(&small(), Zone::Local));
}

// ------------------------------------------------------------------- dash

#[test]
fn dash_charges_by_started_kilogram() {
    let dash = Dash::new("Dash", 300, 120);
    assert_eq!(dash.name(), "Dash");
    assert_eq!(
        dash.price(&small(), Zone::Local),
        Some(540),
        "1500 g are 2 started kilograms"
    );
    assert_eq!(
        dash.price(&letter(), Zone::Local),
        Some(420),
        "50 g are 1 started kilogram"
    );
    assert_eq!(
        dash.price(&medium(), Zone::Local),
        Some(2100),
        "billable 14 400 g: 15 kilograms"
    );
    assert_eq!(
        dash.price(&parcel(1000, (10, 10, 10), GOODS), Zone::Local),
        Some(420)
    );
    assert_eq!(
        dash.price(&parcel(1001, (10, 10, 10), GOODS), Zone::Local),
        Some(540)
    );
}

#[test]
fn dash_multiplies_by_zone() {
    let dash = Dash::new("Dash", 300, 120);
    assert_eq!(dash.price(&small(), Zone::National), Some(1080));
    assert_eq!(dash.price(&small(), NEAR), Some(2700));
    assert_eq!(dash.price(&small(), FAR), None);
    assert_eq!(dash.price(&medium(), NEAR), Some(10_500));
}

#[test]
fn dash_takes_liquid_only_locally() {
    let dash = Dash::new("Dash", 300, 120);
    assert_eq!(dash.price(&bottle(), Zone::Local), Some(420));
    assert_eq!(dash.price(&bottle(), Zone::National), None);
    assert_eq!(dash.price(&bottle(), NEAR), None);
    assert_eq!(dash.price(&bottle(), FAR), None);
}

#[test]
fn dash_keeps_its_own_name() {
    let dash = {
        let name = String::from("Night Rider");
        Dash::new(&name, 1, 1)
    };
    assert_eq!(dash.name(), "Night Rider");
}

#[test]
fn dash_declines_when_the_price_does_not_fit() {
    assert_eq!(
        Dash::new("x", 0, u32::MAX).price(&small(), Zone::Local),
        None
    );
    assert_eq!(
        Dash::new("x", u32::MAX, 1).price(&small(), Zone::Local),
        None
    );
    let pricey = Dash::new("x", 3_000_000_000, 0);
    assert_eq!(pricey.price(&small(), Zone::Local), Some(3_000_000_000));
    assert_eq!(
        pricey.price(&small(), Zone::National),
        None,
        "twice 3 000 000 000 is more than u32::MAX"
    );
    assert_eq!(
        Dash::new("x", u32::MAX, 0).price(&small(), Zone::Local),
        Some(u32::MAX)
    );
}

// ------------------------------------------------------------- discounted

#[test]
fn discount_reduces_the_price_and_rounds_up() {
    let ten = Discounted::new(Snail, 10).unwrap();
    assert_eq!(ten.price(&small(), Zone::Local), Some(360));
    assert_eq!(ten.price(&letter(), Zone::Local), Some(81));
    let fifteen = Discounted::new(Snail, 15).unwrap();
    assert_eq!(
        fifteen.price(&letter(), Zone::National),
        Some(94),
        "85 % of 110 is 93.5; a fraction of a cent is rounded up"
    );
    assert_eq!(
        Discounted::new(Fixed("F", 1), 99)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(1)
    );
}

#[test]
fn discount_limits() {
    assert_eq!(
        Discounted::new(Snail, 0)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(400)
    );
    assert_eq!(
        Discounted::new(Snail, 100)
            .unwrap()
            .price(&small(), Zone::Local),
        Some(0)
    );
    assert!(Discounted::new(Snail, 101).is_none());
    assert!(Discounted::new(Snail, 255).is_none());
}

#[test]
fn discount_keeps_the_name_and_the_refusals() {
    let cheap = Discounted::new(Snail, 50).unwrap();
    assert_eq!(cheap.name(), "Snail Mail");
    assert_eq!(cheap.price(&large(), FAR), None);
    assert!(!cheap.accepts(&large(), FAR));
    assert!(cheap.accepts(&large(), Zone::Local));
    assert_eq!(*cheap.inner(), Snail);
    assert_eq!(cheap.into_inner(), Snail);
}

#[test]
fn discounts_can_be_stacked() {
    let twice = Discounted::new(Discounted::new(Snail, 50).unwrap(), 50).unwrap();
    assert_eq!(twice.price(&small(), Zone::Local), Some(100));
    assert_eq!(twice.name(), "Snail Mail");
}

// ----------------------------------------------------------------- quotes

fn market() -> Vec<Box<dyn Carrier>> {
    vec![
        Box::new(Snail),
        Box::new(Dash::new("Dash", 100, 50)),
        Box::new(Closed),
        Box::new(Discounted::new(Dash::new("Bulk", 5000, 10), 20).unwrap()),
    ]
}

#[test]
fn cheapest_picks_the_lowest_price() {
    let carriers = market();
    // Snail 400, Dash 100 + 2 * 50 = 200, Bulk 80 % of 5020 = 4016.
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("Dash", 200));
    // Snail 1500, Dash 100 + 72 * 50 = 3700, Bulk 80 % of 5720 = 4576.
    let quote = cheapest(&carriers, &large(), Zone::Local).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("Snail Mail", 1500));
    // Snail declines, Dash (100 + 3600) * 5 = 18 500, Bulk 80 % of 28 600 = 22 880.
    let quote = cheapest(&carriers, &large(), NEAR).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("Dash", 18_500));
}

#[test]
fn cheapest_skips_carriers_that_decline() {
    let carriers = market();
    // Only Snail goes far away with a letter.
    let quote = cheapest(&carriers, &letter(), FAR).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("Snail Mail", 400));
    assert!(
        cheapest(&carriers, &large(), FAR).is_none(),
        "nobody takes a large parcel far away"
    );
    assert!(cheapest(&[], &small(), Zone::Local).is_none());
    let closed: Vec<Box<dyn Carrier>> = vec![Box::new(Closed), Box::new(Closed)];
    assert!(cheapest(&closed, &small(), Zone::Local).is_none());
}

#[test]
fn cheapest_prefers_the_earlier_carrier_among_equal_prices() {
    let carriers: Vec<Box<dyn Carrier>> = vec![
        Box::new(Fixed("dear", 900)),
        Box::new(Fixed("first", 500)),
        Box::new(Fixed("second", 500)),
        Box::new(Fixed("third", 500)),
    ];
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("first", 500));
}

#[test]
fn cheapest_handles_a_free_carrier() {
    let carriers: Vec<Box<dyn Carrier>> =
        vec![Box::new(Fixed("paid", 1)), Box::new(Fixed("free", 0))];
    let quote = cheapest(&carriers, &small(), Zone::Local).unwrap();
    assert_eq!((quote.carrier.name(), quote.cents), ("free", 0));
}

#[test]
fn total_adds_the_prices() {
    let parcels = [letter(), small(), medium()];
    assert_eq!(total(&Snail, &parcels, Zone::Local), Some(90 + 400 + 700));
    assert_eq!(
        total(&Snail, &parcels, Zone::National),
        Some(110 + 550 + 950)
    );
    assert_eq!(
        total(&Snail, &parcels, FAR),
        None,
        "Snail declines the medium parcel, so there is no total"
    );
    assert_eq!(total(&Snail, &[], FAR), Some(0));
    assert_eq!(total(&Closed, &[], Zone::Local), Some(0));
}

#[test]
fn total_works_with_and_without_dynamic_dispatch() {
    let parcels = [small(), small()];
    let carriers = market();
    let through_dyn: &dyn Carrier = carriers[1].as_ref();
    assert_eq!(total(through_dyn, &parcels, Zone::Local), Some(400));
    assert_eq!(
        total(&carriers[1], &parcels, Zone::Local),
        Some(400),
        "a Box<dyn Carrier> is a carrier too"
    );
    assert_eq!(
        total(&Dash::new("Dash", 100, 50), &parcels, Zone::Local),
        Some(400)
    );
}

#[test]
fn total_does_not_overflow() {
    let parcels = [small(), small(), small()];
    assert_eq!(
        total(&Fixed("F", u32::MAX), &parcels, Zone::Local),
        Some(3 * u64::from(u32::MAX)),
        "three prices of u32::MAX need a wider type for the sum"
    );
}

#[test]
fn the_root_re_exports_the_same_items() {
    // These lines compile only if both paths name the same type.
    let p: postage::Parcel = small();
    let _: &postage::parcel::Parcel = &p;
    let zone: postage::Zone = postage::carrier::Zone::Local;
    let snail: postage::Snail = Snail;
    let _: postage::SizeClass = p.size_class();
    let _: postage::Grams = p.weight();
    let _: postage::Dimensions = p.dimensions();
    let _: postage::Contents = p.contents();
    let _: Option<postage::Quote<'_>> = None;
    let _: postage::Region = Region::Near;
    let _: postage::Dash = Dash::new("x", 1, 1);
    let _: Option<postage::Discounted<Snail>> = None;
    let _: postage::ParcelError = ParcelError::Side(0);
    fn takes(_: &impl postage::Carrier) {}
    takes(&snail);
    assert_eq!(postage::total(&snail, &[p], zone), Some(400));
    assert!(postage::cheapest(&[], &p, zone).is_none());
}
